# owner: platform
import unittest

from hourglass.rounding import round_spans
from hourglass.parsing import parse_span


class RoundingTests(unittest.TestCase):
    def test_snaps_to_nearest_step(self):
        spans = [parse_span("09:04-17:11"), parse_span("08:08-12:07")]
        self.assertEqual(
            round_spans(spans, 15),
            ["09:00-17:15 (8h 15m)", "08:15-12:00 (3h 45m)"]
        )

    def test_halfway_rounds_up(self):
        self.assertEqual(round_spans([parse_span("09:07-10:37")], 15), ["09:00-10:30 (1h 30m)"])

    def test_empty(self):
        self.assertEqual(round_spans([], 15), [])

    def test_bad_steps_raise(self):
        for step in (0, -15, 7, 45, 90):
            with self.assertRaises(ValueError):
                round_spans([], step)
